static void run_rows(int first, int last) {
    int k;
    for (k = first; k < last; k++) {
        const row_t *r = &rows[k];
        we_unit_ctx_t c;
        int type = -9, milli = 0, rc, ok;
        memset(&c, 0, sizeof(c));
        c.font100 = r->font100; c.root100 = 1600; c.vw = r->vw; c.vh = r->vh; c.vertical = r->vertical;
        rc = we_math_milli(r->expr, (int)strlen(r->expr), &c, r->basis, &type, &milli);
        ok = r->type < 0 ? rc == -1 : rc == 0 && type == r->type && milli == r->milli;
        if (!ok) printf("  row %d: %s: rc %d type %d milli %d\n", k, r->expr, rc, type, milli);
        TEST_ASSERT_TRUE(ok);
    }
}

static void test_l118_math_part0(void) { run_rows(0, 200); }
static void test_l118_math_part1(void) { run_rows(200, 400); }
static void test_l118_math_part2(void) { run_rows(400, 600); }
static void test_l118_math_part3(void) { run_rows(600, 800); }

int main(void) {
    unity_init();
    RUN_TEST(test_l118_math_part0);
    RUN_TEST(test_l118_math_part1);
    RUN_TEST(test_l118_math_part2);
    RUN_TEST(test_l118_math_part3);
    unity_print_results();
    unity_cleanup();
    return unity_stats.tests_failed == 0 ? 0 : 1;
}
